const r = await tools.exec_command({cmd:"python3 - <<'PY'
import hashlib,json,os
from pathlib import Path
m=json.load(open(os.environ['STAMPED_DELIVERY_MANIFEST']))
root=Path(os.environ['STAMPED_JUDGE_TARGET'])
changes=[]; mismatches=[]; present=set()
for e in m['entries']:
 rel=e['path'].removeprefix('content/workspace/'); p=root/rel; present.add(rel)
 if e['kind']=='directory':
  if not p.is_dir(): mismatches.append((rel,'missing/non-dir'))
 elif e['kind']=='symlink':
  if not p.is_symlink(): mismatches.append((rel,'not-symlink'))
  elif os.readlink(p)!=e.get('target'): mismatches.append((rel,'link-target'))
 elif e['kind']=='file':
  if not p.is_file(): mismatches.append((rel,'missing/non-file'))
  else:
   h=hashlib.sha256(p.read_bytes()).hexdigest()
   if h!=e['sha256']:
    allowed=rel in {'.git/annex/keysdb/db','.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'}
    (changes if allowed else mismatches).append((rel,h))
extra=[]
for p in root.rglob('*'):
 rel=p.relative_to(root).as_posix()
 if rel not in present: extra.append(rel)
print('allowed metadata changes',changes)
print('other mismatches',mismatches)
print('unmanifested paths',extra[:30], 'count',len(extra))
PY
cat "$STAMPED_JUDGE_TARGET/.git/HEAD"; rg --files -g 'README*' -g 'Makefile' -g '*requirements*' -g 'pyproject.toml' -g 'environment.yml' -g 'Dockerfile' "$STAMPED_JUDGE_TARGET" ",yield_time_ms:30000,max_output_tokens:2500});
