  if not p.is_symlink(): mismatches.append((rel,'not-symlink'))
  elif os.readlink(p)!=e['link_target']: mismatches.append((rel,'link-target'))
 elif e['kind']=='file':
  if not p.is_file(): mismatches.append((rel,'missing/non-file'))
  elif hashlib.sha256(p.read_bytes()).hexdigest()!=e['sha256']:
   if rel in {'.git/annex/keysdb/db','.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'}: changes.append(rel)
   else: mismatches.append((rel,'sha256'))
extra=[]
for p in root.rglob('*'):
 rel=p.relative_to(root).as_posix()
 if rel not in expected: extra.append(rel)
print(json.dumps({'classified_operational_metadata_changes':changes,'other_mismatches':mismatches,'unmanifested_paths':extra},indent=2))
